from collections import Counter, deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); result=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for z in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     a,b=z
     if 0<=a<h and 0<=b<w and z not in seen and grid[a][b]==col:
      seen.add(z); q.append(z)
   rr=[x for x,y in cells]; cc=[y for x,y in cells]
   result.append((col,cells,min(rr),max(rr),min(cc),max(cc)))
 return result

def transform_v1(grid, threshold=.7):
 h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 cs=comps(grid); out=[row[:] for row in grid]
 for col,cells,r0,r1,c0,c1 in cs:
  if col==bg or len(cells)!=1: continue
  r,c=cells[0]
  candidates=[]
  for color,ccells,a,b,d,e in cs:
   if color==bg or color==col: continue
   area=(b-a+1)*(e-d+1)
   if a<=r<=b and d<=c<=e:
    ratio=(len(ccells)+1)/area
    if ratio>=threshold:
     candidates.append((ratio,area,color))
  if candidates:
   _,_,target=max(candidates, key=lambda x:(x[0],x[1]))
   out[r][c]=target
  else: out[r][c]=bg
 return out
